package proto

import (
	"fmt"
	"testing"
)

// legacyMsg mimics a message generated by protoc-gen-go < v1.4 (APIv1 only:
// no ProtoReflect method).
type legacyMsg struct {
	Value string `protobuf:"bytes,1,opt,name=value,proto3" json:"value,omitempty"`
}

func (m *legacyMsg) Reset()         { *m = legacyMsg{} }
func (m *legacyMsg) String() string { return fmt.Sprintf("%+v", *m) }
func (*legacyMsg) ProtoMessage()    {}

func TestReviewLegacyCodec(t *testing.T) {
	in := &legacyMsg{Value: "hello"}
	b, err := codec{}.Marshal(in)
	if err != nil {
		t.Fatalf("codec.Marshal(APIv1-only message) error: %v", err)
	}
	out := &legacyMsg{}
	if err := codec{}.Unmarshal(b, out); err != nil {
		t.Fatalf("codec.Unmarshal(APIv1-only message) error: %v", err)
	}
	if out.Value != "hello" {
		t.Fatalf("round trip got %q, want %q", out.Value, "hello")
	}
}
EOF
