package status

import (
	"fmt"
	"testing"

	protov1 "github.com/golang/protobuf/proto"
	"google.golang.org/grpc/codes"
)

// reviewLegacyMsg mimics a message generated by protoc-gen-go < v1.4 (APIv1
// only), registered the way such generated code registers itself.
type reviewLegacyMsg struct {
	Value string `protobuf:"bytes,1,opt,name=value,proto3" json:"value,omitempty"`
}

func (m *reviewLegacyMsg) Reset()         { *m = reviewLegacyMsg{} }
func (m *reviewLegacyMsg) String() string { return fmt.Sprintf("%+v", *m) }
func (*reviewLegacyMsg) ProtoMessage()    {}

func init() {
	protov1.RegisterType((*reviewLegacyMsg)(nil), "grpc.review.reviewLegacyMsg")
}

func TestReviewLegacyDetails(t *testing.T) {
	s, err := New(codes.Internal, "x").WithDetails(&reviewLegacyMsg{Value: "v"})
	if err != nil {
		t.Fatalf("WithDetails(APIv1-only message) error: %v", err)
	}
	ds := s.Details()
	if len(ds) != 1 {
		t.Fatalf("Details() returned %d items, want 1", len(ds))
	}
	got, ok := ds[0].(*reviewLegacyMsg)
	if !ok {
		t.Fatalf("Details()[0] has type %T, want *reviewLegacyMsg", ds[0])
	}
	if got.Value != "v" {
		t.Fatalf("Details()[0].Value = %q, want %q", got.Value, "v")
	}
}
EOF
